arguments.command:
cd /tmp && python3 -I - <<'EOF'
src = open('/tmp/Shor_v2.thy').read().split('\n')
def ind(s): return len(s) - len(s.lstrip(' '))
out = []
for line in src:
    if out and line.strip() and ind(line) > ind(out[-1]) and len(out[-1]) + 1 + len(line.strip()) <= 160:
        out[-1] = out[-1] + ' ' + line.strip()
    else:
        out.append(line)
open('/tmp/Shor_v4.thy','w').write('\n'.join(out))
print(len(out))
EOF
cp /tmp/Shor_v4.thy /app/Shor_General.thy && timeout 300 isabelle build -o threads=2 -D /app 2>&1 | tail -15

